const releaseReport = `-- name: ReleaseReport :one
UPDATE reports
SET delivery_state = 'pending', available_at = ?1,
    claim_token = '', claimed_at = NULL, last_error = ?2
WHERE id = ?3 AND delivery_state = 'claimed' AND claim_token = ?4
RETURNING id, session_id, project_id, state, note, message, created_at, delivery_state, available_at, settlement_deadline, repeat_count, claim_token, claimed_at, delivery_attempts, acknowledged_at, last_error, delivery_batch_id
`

type ReleaseReportParams struct {
	AvailableAt time.Time
	LastError   string
	ID          string
	ClaimToken  string
}

func (q *Queries) ReleaseReport(ctx context.Context, arg ReleaseReportParams) (Report, error) {
	row := q.db.QueryRowContext(ctx, releaseReport,
		arg.AvailableAt,
		arg.LastError,
		arg.ID,
		arg.ClaimToken,
	)
	var i Report
	err := row.Scan(
		&i.ID,
		&i.SessionID,
		&i.ProjectID,
		&i.State,
		&i.Note,
		&i.Message,
		&i.CreatedAt,
		&i.DeliveryState,
		&i.AvailableAt,
		&i.SettlementDeadline,
		&i.RepeatCount,
		&i.ClaimToken,
		&i.ClaimedAt,
		&i.DeliveryAttempts,
		&i.AcknowledgedAt,
		&i.LastError,
		&i.DeliveryBatchID,
	)
	return i, err
}

const releaseReportBatch = `-- name: ReleaseReportBatch :many
UPDATE reports
SET delivery_state = 'pending', available_at = min(available_at, ?1),
    claim_token = '', claimed_at = NULL, last_error = ?2
WHERE project_id = ?3 AND delivery_state = 'claimed'
  AND claim_token = ?4
RETURNING id, session_id, project_id, state, note, message, created_at, delivery_state, available_at, settlement_deadline, repeat_count, claim_token, claimed_at, delivery_attempts, acknowledged_at, last_error, delivery_batch_id
`

type ReleaseReportBatchParams struct {
	AvailableAt interface{}
	LastError   string
	ProjectID   string
	ClaimToken  string
}

func (q *Queries) ReleaseReportBatch(ctx context.Context, arg ReleaseReportBatchParams) ([]Report, error) {
	rows, err := q.db.QueryContext(ctx, releaseReportBatch,
		arg.AvailableAt,
		arg.LastError,
		arg.ProjectID,
		arg.ClaimToken,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Report{}
	for rows.Next() {
		var i Report
		if err := rows.Scan(
			&i.ID,
			&i.SessionID,
			&i.ProjectID,
			&i.State,
			&i.Note,
			&i.Message,
			&i.CreatedAt,
			&i.DeliveryState,
			&i.AvailableAt,
			&i.SettlementDeadline,
			&i.RepeatCount,
			&i.ClaimToken,
			&i.ClaimedAt,
			&i.DeliveryAttempts,
			&i.AcknowledgedAt,
			&i.LastError,
			&i.DeliveryBatchID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reportChatReceipt = `-- name: ReportChatReceipt :one
SELECT d.message_id, d.client_message_id, d.turn_id,
       CAST(coalesce(t.provider_turn_id, d.provider_turn_id) AS TEXT) AS provider_turn_id,
       CAST(coalesce(t.state, '') AS TEXT) AS state, d.provider_conversation_id, d.submitted_at, d.accepted_at
FROM report_chat_deliveries d
LEFT JOIN conversation_turns t ON t.id = d.turn_id
WHERE d.batch_id = ?
`

type ReportChatReceiptRow struct {
	MessageID              string
	ClientMessageID        string
	TurnID                 string
	ProviderTurnID         string
	State                  string
	ProviderConversationID string
	SubmittedAt            sql.NullTime
	AcceptedAt             sql.NullTime
}

func (q *Queries) ReportChatReceipt(ctx context.Context, batchID string) (ReportChatReceiptRow, error) {
	row := q.db.QueryRowContext(ctx, reportChatReceipt, batchID)
	var i ReportChatReceiptRow
	err := row.Scan(
		&i.MessageID,
		&i.ClientMessageID,
		&i.TurnID,
		&i.ProviderTurnID,
		&i.State,
		&i.ProviderConversationID,
		&i.SubmittedAt,
		&i.AcceptedAt,
	)
	return i, err
}

const requeueClaimedReports = `-- name: RequeueClaimedReports :execrows
UPDATE reports
SET delivery_state = 'pending', claim_token = '', claimed_at = NULL,
    last_error = 'delivery claim recovered after daemon restart'
WHERE delivery_state = 'claimed'
`

func (q *Queries) RequeueClaimedReports(ctx context.Context) (int64, error) {
	result, err := q.db.ExecContext(ctx, requeueClaimedReports)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
